-- Modify "products" table
ALTER TABLE "products" ADD COLUMN "points_required" bigint NOT NULL DEFAULT 0;
-- Create "license_orders" table
CREATE TABLE "license_orders" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "plan" character varying NOT NULL, "amount" bigint NOT NULL, "status" character varying NOT NULL DEFAULT 'pending', "payer_user_id" bigint NOT NULL, "instance_id" character varying NOT NULL, "domain" character varying NULL, "features" jsonb NULL, "expires_at" timestamptz NOT NULL, "license_file" text NULL, "paid_at" timestamptz NULL, PRIMARY KEY ("id"));
-- Create index "licenseorder_instance_id" to table: "license_orders"
CREATE INDEX "licenseorder_instance_id" ON "license_orders" ("instance_id");
-- Create index "licenseorder_payer_user_id" to table: "license_orders"
CREATE INDEX "licenseorder_payer_user_id" ON "license_orders" ("payer_user_id");
